package com.example.spring_blog.payment;import com.example.spring_blog.user.SessionUserDTO;import com.example.spring_blog.util.Define;import jakarta.servlet.http.HttpSession;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RestController;import java.util.Map;@RestController@RequiredArgsConstructorpublic class PaymentApiController {    private final PortOnePaymentService portOnePaymentService;    @PostMapping("/api/payment/prepare")    public ResponseEntity<?> prepare(@RequestBody PaymentRequest.PrepareDTO prepareDTO, HttpSession session) {        SessionUserDTO sessionUserDTO = (SessionUserDTO) session.getAttribute(Define.SESSION_USER);        if (sessionUserDTO == null) {            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)                    .body(Map.of("message", "로그인이 필요합니다."));        }        prepareDTO.validate();        return ResponseEntity.ok(portOnePaymentService.prepare(sessionUserDTO.getId(), prepareDTO.getAmount()));    }    @PostMapping("/api/payment/complete")    public ResponseEntity<?> complete(@RequestBody PaymentRequest.CompleteDTO completeDTO, HttpSession session) {        SessionUserDTO sessionUserDTO = (SessionUserDTO) session.getAttribute(Define.SESSION_USER);        if (sessionUserDTO == null) {            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)                    .body(Map.of("message", "로그인이 필요합니다."));        }        completeDTO.validate();        return ResponseEntity.ok(portOnePaymentService.complete(sessionUserDTO.getId(), completeDTO.getPaymentId()));    }}